from fastapi import FastAPI, Response, Depends
from typing import Annotated
from fastapi.testclient import TestClient

def modify_response():
    return Response(content="modified", media_type="text/plain")

app = FastAPI()

@app.get("/test1")
def endpoint1(response: Annotated[Response, Depends(modify_response)]):
    return {"message": "ok"}

@app.get("/test2")
def endpoint2(response: Response = Depends(modify_response)):
    return {"message": "ok"}

@app.get("/test3")
def endpoint3(response: Response):
    return {"message": "ok"}

client = TestClient(app)

try:
    print("Testing endpoint1...")
    client.get("/test1")
    print("endpoint1 success")

    print("Testing endpoint2...")
    client.get("/test2")
    print("endpoint2 success")

    print("Testing endpoint3...")
    client.get("/test3")
    print("endpoint3 success")

    print("All tests passed!")
except Exception as e:
    print(f"Test failed: {e}")
    import traceback
    traceback.print_exc()
