from fastapi import FastAPI, Response, Depends, Body
from typing import Annotated
from fastapi.testclient import TestClient
from fastapi.dependencies.utils import analyze_param
import inspect

# We can try to trigger the analyze_param directly or use the app
app = FastAPI()

try:
    @app.get("/fail")
    def endpoint(response: Annotated[Response, Body()]):
        return {"message": "ok"}

    # Trigger the analysis by making a request or just inspecting the route
    # FastAPI analyzes params during app startup or first request
    client = TestClient(app)
    client.get("/fail")
except Exception as e:
    print(f"Caught expected error: {e}")
except AssertionError as e:
    print(f"Caught expected AssertionError: {e}")
except Exception as e:
    print(f"Caught unexpected error: {type(e).__name__}: {e}")
EOF
